		let pkt_len = 19;
		if (PacketVerManager_default.value >= 20210630) pkt_len += 4;
		const pkt_buf = new BinaryWriter(pkt_len);
		pkt_buf.writeShort(1078);
		pkt_buf.writeULong(this.AID);
