	PACKET.CZ.NPC_EXPANDED_BARTER_MARKET_PURCHASE.prototype.build = function() {
		const item_size = PacketVerManager_default.value >= 20181121 ? 12 : 10;
		const pkt_len = 4 + this.itemList.length * item_size;
		const pkt_buf = new BinaryWriter(pkt_len);
		pkt_buf.writeShort(2903);
		pkt_buf.writeShort(pkt_len);
		for (let i = 0; i < this.itemList.length; ++i) {
			if (PacketVerManager_default.value >= 20181121) pkt_buf.writeULong(this.itemList[i].itemId);
			else pkt_buf.writeUShort(this.itemList[i].itemId);
			pkt_buf.writeULong(this.itemList[i].shopIndex);
			pkt_buf.writeULong(this.itemList[i].amount);
		}
		return pkt_buf;
	};
