	PACKET.ZC.NPC_EXPANDED_BARTER_MARKET_ITEMINFO = function PACKET_ZC_NPC_EXPANDED_BARTER_MARKET_ITEMINFO(fp, end) {
		const self = this;
		self.items_count = fp.readLong();
		self.itemList = (function() {
			const item_size = PacketVerManager_default.value >= 20250402 ? 36 : PacketVerManager_default.value >= 20210203 ? 32 : PacketVerManager_default.value >= 20181121 ? 26 : 24;
			const sub2_size = PacketVerManager_default.value >= 20181121 ? 12 : 10;
			const items = [];
			for (let i = 0; i < self.items_count; ++i) {
				if (fp.tell() + item_size > end) {
					console.error("Attempted to read beyond packet bounds");
					break;
				}
				const item = {};
				item.ITID = PacketVerManager_default.value >= 20181121 ? fp.readULong() : fp.readUShort();
				item.type = fp.readUShort();
				item.amount = fp.readULong();
				item.weight = fp.readULong();
				item.index = fp.readULong();
				item.price = fp.readULong();
				item.viewSprite = PacketVerManager_default.value >= 20210203 ? fp.readUShort() : 0;
				item.location = PacketVerManager_default.value >= 20210203 ? fp.readULong() : 0;
				item.currency_count = fp.readULong();
				item.RefiningLevel = PacketVerManager_default.value >= 20250402 ? fp.readULong() : 0;
				item.currencyList = [];
				for (let j = 0; j < item.currency_count; ++j) {
					if (fp.tell() + sub2_size > end) {
						console.error("Attempted to read beyond packet bounds in currencies");
						break;
					}
					const currency = {};
					currency.ITID = PacketVerManager_default.value >= 20181121 ? fp.readULong() : fp.readUShort();
					currency.refine_level = fp.readUShort();
					currency.amount = fp.readULong();
					currency.type = fp.readUShort();
					item.currencyList.push(currency);
				}
				items.push(item);
			}
			return items;
		})();
	};
	PACKET.ZC.NPC_EXPANDED_BARTER_MARKET_ITEMINFO.size = -1;
