		/**
		* @return {string} path to body sprite/action
		* @param {number} id entity
		* @param {boolean} sex
		* @param {number} alternative sprite
		* @return {string}
		*/
		static getBodyPath(id, sex, alternative = -1, cashMountCostume = false) {
			if (id === 45) return null;
			if (id === 111 || id === 139 || id == 2337) return null;
			if (DB.isPlayer(id)) {
				let result = DB.isDoram(id) ? "data/sprite/µµ¶÷Á·/¸öÅë/" : "data/sprite/ÀÎ°£Á·/¸öÅë/";
				result += SexTable[sex] + "/";
				if (PacketVerManager_default.value > 20141022 && alternative > 0 && id !== alternative) {
					const use_costume = alternative > JobConst_default.COSTUME_SECOND_JOB_START && alternative < JobConst_default.COSTUME_SECOND_JOB_END;
					if (use_costume) result += "costume_1/";
					result += (cashMountCostume ? JobNameTable[id] : JobNameTable[alternative]) || JobNameTable[0];
					result += "_" + SexTable[sex];
					if (use_costume) result += "_1";
					return result;
				}
				result += JobNameTable[id] || JobNameTable[0];
				result += "_" + SexTable[sex];
				return result;
			}
			if (DB.isNPC(id)) return "data/sprite/npc/" + (MonsterTable_default[id] || MonsterTable_default[46]).toLowerCase();
			if (DB.isMercenary(id)) return "data/sprite/ÀÎ°£Á·/¸öÅë/" + MonsterTable_default[id];
			if (DB.isHomunculus(id)) return "data/sprite/homun/" + (MonsterTable_default[id] || MonsterTable_default[1002]).toLowerCase();
			switch (id) {
				case "11_FALCON":
				case "4034_FALCON": return "data/sprite/ÀÌÆÑÆ®/¸Å";
				case "4012_FALCON": return "data/sprite/ÀÌÆÑÆ®/¸Å2";
				case "4056_FALCON":
				case "4062_FALCON":
				case "4098_FALCON": return "data/sprite/ÀÌÆÑÆ®/owl";
				case "4257_FALCON":
				case "4270_FALCON":
				case "4278_FALCON": return "data/sprite/ÀÌÆÑÆ®/windhawk_hawk";
				case "4056_WUG":
				case "4062_WUG":
				case "4098_WUG": return "data/sprite/¸ó½ºÅÍ/¿ö±×";
				case "4257_WUG": return "data/sprite/ÀÌÆÑÆ®/windhawk_wolf";
				default: if (typeof id === "string") {
					if (id.includes("_FALCON")) return "data/sprite/ÀÌÆÑÆ®/¸Å";
					else if (id.includes("_WUG")) return "data/sprite/¸ó½ºÅÍ/¿ö±×";
				}
			}
			return "data/sprite/¸ó½ºÅÍ/" + (MonsterTable_default[id] || MonsterTable_default[1001]).toLowerCase();
		}
