/**
* Prettify number (15000 -> 15,000)
*
* @param {number}
* @return {string}
*/
function prettifyZeny(value) {
	const num = String(value);
	let i = 0;
	const len = num.length;
	let out = "";
	while (i < len) {
		out = num[len - i - 1] + out;
		if ((i + 1) % 3 === 0 && i + 1 !== len) out = "," + out;
		++i;
	}
	return out;
}
